    // Console-id → icon registry. Aliases map to the same Def, so a
    // future console-metadata source-of-truth can grow this without
    // touching forConsole().
    private val Defs: Map<String, Def> = mapOf(
        "nes" to Nes,
        "snes" to Snes, "gb" to Snes, "gba" to Snes, "gbc" to Snes,
        "n64" to N64,
        "genesis" to Genesis, "gen" to Genesis, "sat" to Genesis,
        "psx" to Psx, "psp" to Psx, "dc" to Psx,
    )

    private val Cache = mutableMapOf<Pair<String, Int>, ImageVector>()

    /**
     * Controller icon for the given console id. Unknown ids fall back to
     * the SNES outline (matches the prior hand-rolled lookup behaviour
     * so call sites can render unconditionally). [fill] determines the
     * inner path fill — call sites that wrap the result in
     * `Image(..., colorFilter = ColorFilter.tint(...))` can leave the
     * default; the tint overrides it.
     */
    fun forConsole(
        consoleId: String,
        fill: Brush = SolidColor(Color.Black),
    ): ImageVector {
        val key = consoleId.lowercase()
        val def = Defs[key] ?: Defs.getValue("snes")
        return Cache.getOrPut(def.name to fill.hashCode()) { build(def, fill) }
    }

    private fun build(def: Def, fill: Brush): ImageVector =
        ImageVector.Builder(
            name = def.name,
            defaultWidth = 64.dp,
            defaultHeight = 64.dp,
            viewportWidth = 64f,
            viewportHeight = 64f,
        ).apply {
            addPath(
                pathData = PathParser().parsePathString(def.pathData).toNodes(),
                fill = fill,
            )
        }.build()
}
